import { useRef, useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import KeyboardArrowDown from '@mui/icons-material/KeyboardArrowDown';
import CheckIcon from '@mui/icons-material/Check';
import UndoIcon from '@mui/icons-material/Undo';
import SentimentDissatisfiedIcon from '@mui/icons-material/SentimentDissatisfied';
import { getProgrammes, recognizeFaces, markAttendanceBatch, lookupByBadge } from '../../services/api';
import QrScanner from '../../components/qr_scanner/QrScanner';
import EmptyState from '../../components/shared/EmptyState';
import { useConnectivity } from '../../hooks/useConnectivity';

const MODEL_URL = 'https://cdn.jsdelivr.net/gh/justadudewhohacks/face-api.js@0.22.2/weights/';
const DETECTION_FRAME_SKIP = 8;

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

export default function CameraPage() {
    const navigate = useNavigate();
    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }
    if (currentUser.role !== 'staff') {
        navigate('/');
        return null;
    }

    const videoRef = useRef(null);
    const canvasRef = useRef(null);
    const displaySizeRef = useRef(null);
    const rafRef = useRef(null);
    const cancelledRef = useRef(false);
    const frameCountRef = useRef(0);
    const scanKeyRef = useRef(0);

    const { isOnline } = useConnectivity();

    const [programmes, setProgrammes] = useState([]);
    const [programmeId, setProgrammeId] = useState(null);
    const [showPicker, setShowPicker] = useState(false);

    const [error, setError] = useState(null);
    const [status, setStatus] = useState('Loading face detection models...');
    const [facingMode, setFacingMode] = useState('user');
    const [captured, setCaptured] = useState(false);
    const [capturedImage, setCapturedImage] = useState(null);
    const [recognizing, setRecognizing] = useState(false);
    const [matches, setMatches] = useState([]);
    const [selected, setSelected] = useState(new Set());
    const [confirming, setConfirming] = useState(false);
    const [done, setDone] = useState(false);
    const [mode, setMode] = useState('facial');

    useEffect(() => {
        getProgrammes()
            .then((list) => {
                setProgrammes(list);
                if (list.length > 0) setProgrammeId(list[0].id);
            })
            .catch((e) => setError(e.message));
    }, []);

    const stopStream = useCallback(() => {
        if (rafRef.current) cancelAnimationFrame(rafRef.current);
        if (videoRef.current?.srcObject) {
            videoRef.current.srcObject.getTracks().forEach((t) => t.stop());
            videoRef.current.srcObject = null;
        }
    }, []);

    const startCamera = useCallback(async (mode) => {
        try {
            await Promise.all([
                faceapi.nets.ssdMobilenetv1.loadFromUri(MODEL_URL),
            ]);
            if (cancelledRef.current) return;
            setStatus('Starting camera...');

            if (!navigator.mediaDevices?.getUserMedia) {
                throw new Error('Camera access requires HTTPS. Access this page via HTTPS or localhost.');
            }
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { facingMode: mode },
            });
            if (cancelledRef.current) return;
            const video = videoRef.current;
            if (!video) return;
            video.srcObject = stream;

            await new Promise((resolve) => {
                video.addEventListener('loadedmetadata', resolve, { once: true });
            });

            if (cancelledRef.current) return;
            try {
                await video.play();
            } catch (playErr) {
                if (!cancelledRef.current) setError(playErr.message);
                return;
            }

            const { videoWidth, videoHeight } = video;
            const canvas = canvasRef.current;
            const renderedWidth = video.offsetWidth || videoWidth;
            const renderedHeight = video.offsetHeight || videoHeight;
            const displaySize = { width: renderedWidth, height: renderedHeight };
            displaySizeRef.current = displaySize;

            faceapi.matchDimensions(canvas, displaySize);

            setStatus('Detecting faces...');
            detectLoop();
        } catch (err) {
            if (!cancelledRef.current) setError(err.message);
        }
    }, []);

    useEffect(() => {
        cancelledRef.current = false;
        setCaptured(false);
        setCapturedImage(null);
        setMatches([]);
        setSelected(new Set());
        setConfirming(false);
        setDone(false);
        stopStream();
        if (mode === 'facial') {
            startCamera(facingMode);
        }

        return () => {
            cancelledRef.current = true;
            stopStream();
        };
    }, [facingMode, startCamera, stopStream, programmeId, mode]);

    function detectLoop() {
        if (cancelledRef.current) return;
        const video = videoRef.current;
        const canvas = canvasRef.current;
        if (!video || !canvas || video.readyState < 2) {
            rafRef.current = requestAnimationFrame(detectLoop);
            return;
        }

        frameCountRef.current += 1;
        if (frameCountRef.current % DETECTION_FRAME_SKIP !== 0) {
            rafRef.current = requestAnimationFrame(detectLoop);
            return;
        }

        faceapi
            .detectAllFaces(video, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.5 }))
            .then((detections) => {
                const ctx = canvas.getContext('2d');
                ctx.clearRect(0, 0, canvas.width, canvas.height);

                const displaySize = displaySizeRef.current;
                const resized = faceapi.resizeResults(detections, displaySize);

                if (facingMode === 'user') {
                    ctx.save();
                    ctx.translate(canvas.width, 0);
                    ctx.scale(-1, 1);
                }

                resized.forEach((d) => {
                    const box = d.box;
                    ctx.strokeStyle = '#00ff00';
                    ctx.lineWidth = 4;
                    ctx.strokeRect(box.x, box.y, box.width, box.height);
                });

                if (facingMode === 'user') {
                    ctx.restore();
                }

                rafRef.current = requestAnimationFrame(detectLoop);
            })
            .catch((err) => {
                if (!cancelledRef.current) setError(err.message);
            });
    }

    function toggleCamera() {
        setFacingMode((prev) => (prev === 'user' ? 'environment' : 'user'));
    }

    async function handleCapture() {
        if (!programmeId) {
            setError('Please select a programme first');
            return;
        }

        const video = videoRef.current;
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        if (facingMode === 'user') {
            const ctx = canvas.getContext('2d');
            ctx.save();
            ctx.translate(canvas.width, 0);
            ctx.scale(-1, 1);
            ctx.drawImage(video, 0, 0);
            ctx.restore();
        } else {
            canvas.getContext('2d').drawImage(video, 0, 0);
        }

        cancelledRef.current = true;
        stopStream();

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
        setCapturedImage(imageBase64);
        setCaptured(true);
        setRecognizing(true);

        try {
            const result = await recognizeFaces(programmeId, imageBase64);
            setMatches(result.matches);
            setSelected(new Set(result.matches.map((m) => m.delegateId)));
        } catch (e) {
            setError(e.message);
        } finally {
            setRecognizing(false);
        }
    }

    function toggleMatch(delegateId) {
        setSelected((prev) => {
            const next = new Set(prev);
            if (next.has(delegateId)) next.delete(delegateId);
            else next.add(delegateId);
            return next;
        });
    }

    async function handleConfirm() {
        if (selected.size === 0 || !programmeId) return;
        setConfirming(true);
        try {
            const records = Array.from(selected).map((delegateId) => ({
                delegateId,
                status: 'present',
                method: mode === 'qr' ? 'qr' : 'auto',
            }));
            await markAttendanceBatch(programmeId, records);
            setDone(true);
        } catch (e) {
            setError(e.message);
        } finally {
            setConfirming(false);
        }
    }

    function handleRetake() {
        cancelledRef.current = false;
        setCaptured(false);
        setCapturedImage(null);
        setMatches([]);
        setSelected(new Set());
        setConfirming(false);
        setDone(false);
        setError(null);
        scanKeyRef.current += 1;
        if (mode === 'facial') {
            startCamera(facingMode);
        }
    }

    const currentProgramme = programmes.find((p) => p.id === programmeId);

    async function handleQrScan(decodedText) {
        if (!programmeId) return;
        setRecognizing(true);
        setCaptured(true);
        setStatus('Looking up badge...');
        try {
            const result = await lookupByBadge(programmeId, decodedText);
            setMatches(result.matches.map((m) => ({
                delegateId: m.delegateId,
                name: m.name,
                confidence: null,
                imageData: null,
            })));
            setSelected(new Set(result.matches.map((m) => m.delegateId)));
            if (result.errors.length > 0) {
                setError(result.errors.join('; '));
            }
        } catch (e) {
            setError(e.message);
        } finally {
            setRecognizing(false);
        }
    }

    function handleModeChange(newMode) {
        if (newMode === mode) return;
        cancelledRef.current = true;
        stopStream();
        setCaptured(false);
        setCapturedImage(null);
        setMatches([]);
        setSelected(new Set());
        setConfirming(false);
        setDone(false);
        setError(null);
        cancelledRef.current = false;
        setMode(newMode);
    }

    return (
        <main className="page">
            <header className="topbar">
                <div className="topbar-content">
                    <h1 className="page-title">{mode === 'facial' ? 'Facial Recognition' : 'QR Code Scanner'}</h1>
                </div>
                <div className="header-actions">
                    <div className="relative">
                        <button
                            className="btn btn-sm btn-secondary"
                            onClick={() => setShowPicker((p) => !p)}
                        >
                            {currentProgramme?.name || 'Select'}
                            <KeyboardArrowDown className="text-base" />
                        </button>
                        {showPicker && (
                            <div className="absolute top-full left-0 z-20 mt-1 min-w-[180px] rounded-xl border border-edge bg-surface-2 p-1 shadow-xl">
                                {programmes.map((p) => (
                                    <button
                                        key={p.id}
                                        className={`row-clickable block w-full rounded-lg px-3 py-2 text-left text-xs font-medium ${
                                            p.id === programmeId ? 'bg-accent/10 text-accent' : 'text-ink hover:bg-white/5'
                                        }`}
                                        onClick={() => { setProgrammeId(p.id); setShowPicker(false); }}
                                    >
                                        {p.name}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </header>

            {error && (
                <div className="banner banner-error mx-4 mb-3">
                    <span>{error}</span>
                    <button className="underline" onClick={() => setError(null)}>Dismiss</button>
                </div>
            )}

            <div className="px-4 pb-3">
                <div className="segmented mx-auto max-w-[260px]">
                    <button
                        className={`segmented-btn ${mode === 'facial' ? 'segmented-btn-active' : ''}`}
                        onClick={() => handleModeChange('facial')}
                    >
                        Face Recognition
                    </button>
                    <button
                        className={`segmented-btn ${mode === 'qr' ? 'segmented-btn-active' : ''}`}
                        onClick={() => handleModeChange('qr')}
                    >
                        QR Code
                    </button>
                </div>
            </div>

            {!captured ? (
                <>
                    {mode === 'facial' && status !== 'Detecting faces...' && (
                        <p className="camera-status">{status}</p>
                    )}
                    {mode === 'qr' && (
                        <p className="camera-status">Point camera at a QR code</p>
                    )}

                    <div className="px-4">
                        <div className="camera-frame">
                            {mode === 'facial' && (
                                <>
                                    <video
                                        ref={videoRef}
                                        autoPlay
                                        muted
                                        playsInline
                                        className="camera-video"
                                        style={{ transform: facingMode === 'user' ? 'scaleX(-1)' : 'none' }}
                                    />
                                    <canvas
                                        ref={canvasRef}
                                        className="camera-canvas"
                                    />
                                </>
                            )}
                            {mode === 'qr' && (
                                <QrScanner
                                    key={scanKeyRef.current}
                                    onScan={handleQrScan}
                                    onError={(msg) => setError(msg)}
                                    facingMode={facingMode}
                                />
                            )}
                        </div>
                    </div>

                    <div className="camera-actions">
                        {mode === 'facial' && (
                            <button
                                className="btn btn-primary"
                                disabled={!programmeId || !isOnline}
                                onClick={handleCapture}
                            >
                                {isOnline ? 'Capture & Recognize' : 'Unavailable while offline'}
                            </button>
                        )}
                        <button
                            className="btn btn-secondary"
                            onClick={toggleCamera}
                        >
                            Switch to {facingMode === 'user' ? 'Back' : 'Front'}
                        </button>
                    </div>
                </>
            ) : (
                <div className="px-4 pb-6">
                    {recognizing ? (
                        <div className="flex flex-col items-center gap-3 pt-8">
                            <div className="spinner" />
                            <p className="meta">{mode === 'facial' ? 'Recognizing faces...' : 'Looking up badge...'}</p>
                        </div>
                    ) : done ? (
                        <div className="flex flex-col items-center gap-4 pt-8">
                            <div className="flex h-14 w-14 items-center justify-center rounded-full bg-ok-dim text-ok">
                                <CheckIcon />
                            </div>
                            <p className="title">Attendance marked</p>
                            <p className="meta">{selected.size} delegate(s) checked in</p>
                            <button
                                className="btn btn-primary"
                                onClick={handleRetake}
                            >
                                Scan Again
                            </button>
                        </div>
                    ) : (
                        <>
                            <p className="title mb-2">
                                Matches ({matches.length})
                            </p>

                            {matches.length === 0 ? (
                                <EmptyState
                                    icon={<SentimentDissatisfiedIcon />}
                                    title="No matching delegates"
                                    action={(
                                        <button
                                            className="btn btn-primary"
                                            onClick={handleRetake}
                                        >
                                            Try Again
                                        </button>
                                    )}
                                />
                            ) : (
                                <div className="mb-4 space-y-2">
                                    {matches.map((m) => {
                                        const isSelected = selected.has(m.delegateId);
                                        return (
                                            <div
                                                key={m.delegateId}
                                                className={`match-row ${isSelected ? 'match-row-active' : ''}`}
                                                onClick={() => toggleMatch(m.delegateId)}
                                            >
                                                <div className="row-left">
                                                    {m.imageData ? (
                                                        <img
                                                            src={`data:image/jpeg;base64,${m.imageData}`}
                                                            alt={m.name}
                                                            className="h-8 w-8 rounded-full object-cover"
                                                        />
                                                    ) : (
                                                        <div className="avatar avatar-sm avatar-neutral">
                                                            {m.name.charAt(0)}
                                                        </div>
                                                    )}
                                                    <div className="row-text">
                                                        <p className="row-title">{m.name}</p>
                                                        {m.confidence !== null && (
                                                            <p className="meta">
                                                                Confidence: {Math.round(m.confidence * 100)}%
                                                            </p>
                                                        )}
                                                    </div>
                                                </div>
                                                <div className={`match-check ${isSelected ? 'match-check-filled' : 'match-check-empty'}`}>
                                                    {isSelected && <CheckIcon />}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}

                            {matches.length > 0 && (
                                <div className="flex gap-2">
                                    <button
                                        className="btn btn-primary flex-1"
                                        disabled={selected.size === 0 || confirming || !isOnline}
                                        onClick={handleConfirm}
                                    >
                                        {confirming ? 'Marking...' : !isOnline ? 'Unavailable while offline' : `Confirm (${selected.size})`}
                                    </button>
                                    <button
                                        className="btn btn-secondary"
                                        onClick={handleRetake}
                                    >
                                        <UndoIcon />
                                    </button>
                                </div>
                            )}
                        </>
                    )}
                </div>
            )}
        </main>
    );
}

