    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }

    return (
        <main className="page">
            <header className="topbar">
                <h1 className="page-title">Your Badge</h1>
            </header>

            <div className="space-y-4 px-4 pb-6">
                <p className="meta">Your digital badge for check-in. Show the QR code below to staff at any checkpoint.</p>

                <div className="badge-card">
                    <div className="badge-qr flex justify-center">
                        <QRCodeCanvas
                            value={currentUser.id}
                            size={200}
                            bgColor="#ffffff"
                            fgColor="#0f172a"
                            level="M"
                        />
                    </div>

                    <p className="title mt-4 text-center">{currentUser.name}</p>
                    <p className="meta mt-0.5 text-center">{currentUser.email}</p>

                    <div className="badge-namebox mt-4">
                        <p className="break-all font-mono text-[10px] text-muted select-all">
                            {currentUser.id}
                        </p>
                    </div>
                </div>

                <p className="meta mx-auto max-w-[280px] text-center">
                    Show this QR code to staff to check in. The code encodes your account UUID.
                </p>
            </div>
        </main>
    );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { getProgrammes } from "../../services/api";
import GroupsIcon from "@mui/icons-material/Groups";
import SettingsIcon from "@mui/icons-material/Settings";
import CameraAltIcon from "@mui/icons-material/CameraAlt";

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return null; }
}

export default function StaffLandingPage() {
    const navigate = useNavigate();
    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }

    const [programmes, setProgrammes] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        getProgrammes()
            .then(setProgrammes)
            .catch(() => {})
            .finally(() => setLoading(false));
    }, []);

    const activeProgrammes = programmes.filter(p => p.status === 'active');
    const totalDelegates = programmes.reduce((sum, p) => sum + (p.totalDelegates || 0), 0);
    const totalChecked = programmes.reduce((sum, p) => sum + (p.checkedIn || 0), 0);

    return (
        <main className="page">
            <header className="topbar">
                <h1 className="page-title">Welcome, {currentUser.name}</h1>
            </header>

            <div className="space-y-5 px-4 pb-6">
                <p className="meta">Manage your programmes, check in delegates, and monitor attendance.</p>

                {!loading && programmes.length > 0 && (
                    <div className="grid grid-cols-2 gap-3">
                        <div className="card-pad text-center">
                            <p className="text-3xl font-bold text-ink">{activeProgrammes.length}</p>
                            <p className="meta mt-1">Active programmes</p>
                        </div>
                        <div className="card-pad text-center">
                            <p className="text-3xl font-bold text-ink">{totalChecked}/{totalDelegates}</p>
                            <p className="meta mt-1">Total check-ins</p>
                        </div>
                    </div>
                )}

                {loading && (
                    <div className="grid grid-cols-2 gap-3">
                        <div className="skeleton-card">
                            <div className="skeleton mx-auto h-8 w-16" />
                        </div>
                        <div className="skeleton-card">
                            <div className="skeleton mx-auto h-8 w-16" />
                        </div>
                    </div>
                )}

                <div className="space-y-2">
                    <p className="section-title">Quick Actions</p>
                    <button className="row row-clickable card w-full text-left" onClick={() => navigate("/dashboard")}>
                        <div className="row-left">
                            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-accent/15 text-accent"><GroupsIcon /></div>
                            <div className="row-text">
                                <p className="row-title">Dashboard</p>
                                <p className="row-meta">View live attendance</p>
                            </div>
                        </div>
                    </button>
                    <button className="row row-clickable card w-full text-left" onClick={() => navigate("/programmes")}>
                        <div className="row-left">
                            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-accent/15 text-accent"><SettingsIcon /></div>
                            <div className="row-text">
                                <p className="row-title">Manage Programmes</p>
                                <p className="row-meta">Create and edit programmes</p>
                            </div>
                        </div>
                    </button>
                    <button className="row row-clickable card w-full text-left" onClick={() => navigate("/camera")}>
                        <div className="row-left">
                            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-accent/15 text-accent"><CameraAltIcon /></div>
                            <div className="row-text">
                                <p className="row-title">Camera</p>
                                <p className="row-meta">Face recognition & QR check-in</p>
                            </div>
                        </div>
                    </button>
                </div>
            </div>
        </main>
    );
}

import { useEffect, useRef, useCallback } from 'react';
import { Html5Qrcode } from 'html5-qrcode';

const SCANNER_ID = 'openglimpse-qr-scanner';

export default function QrScanner({ onScan, onError, facingMode }) {
    const containerRef = useRef(null);
    const canvasRef = useRef(null);
    const qrRef = useRef(null);
    const canvasSizedRef = useRef(false);

    const updateCanvasSize = useCallback(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current?.parentElement;
        if (!canvas || !container) return;
        const rect = container.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
            canvas.width = rect.width;
            canvas.height = rect.height;
            canvasSizedRef.current = true;
        }
    }, []);

    useEffect(() => {
        const container = containerRef.current;
        if (!container) return;

        canvasSizedRef.current = false;

        const qrCode = new Html5Qrcode(SCANNER_ID);
        qrRef.current = qrCode;

        qrCode.start(
            { facingMode },
            { fps: 10, qrbox: { width: 250, height: 250 } },
            (decodedText, decodedResult) => {
                if (!canvasSizedRef.current) updateCanvasSize();

                const canvas = canvasRef.current;
                if (canvas && decodedResult) {
                    const ctx = canvas.getContext('2d');
                    ctx.clearRect(0, 0, canvas.width, canvas.height);

                    const pts = decodedResult.cornerPoints;
                    if (pts && pts.length === 4) {
                        ctx.strokeStyle = '#00ff00';
                        ctx.lineWidth = 4;
                        ctx.beginPath();
                        ctx.moveTo(pts[0].x, pts[0].y);
                        for (let i = 1; i < pts.length; i++) {
                            ctx.lineTo(pts[i].x, pts[i].y);
                        }
                        ctx.closePath();
                        ctx.stroke();

                        const midX = pts.reduce((s, p) => s + p.x, 0) / 4;
                        const midY = pts.reduce((s, p) => s + p.y, 0) / 4;
                        ctx.fillStyle = '#00ff00';
                        ctx.font = 'bold 14px sans-serif';
                        ctx.textAlign = 'center';
                        ctx.fillText('✓ Verified', midX, midY - 10);
                    } else if (decodedResult.boundingBox) {
                        const b = decodedResult.boundingBox;
                        ctx.strokeStyle = '#00ff00';
                        ctx.lineWidth = 4;
                        ctx.strokeRect(b.x, b.y, b.width, b.height);
                    }
                }

                onScan(decodedText);
                qrCode.stop().catch(() => {});
            },
            () => {}
        ).catch((err) => {
            if (onError) onError(err.message || 'Failed to start QR scanner');
        });

        updateCanvasSize();

        const ro = new ResizeObserver(() => updateCanvasSize());
        ro.observe(container.parentElement);

        return () => {
            ro.disconnect();
            qrCode.stop().catch(() => {});
        };
